document.querySelectorAll('[data-lab="L13-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const zh=root.dataset.lang==='zh',data=JSON.parse(root.querySelector('[data-cluster-data]').textContent),r=root.querySelector('[data-radius]'),f=root.querySelector('[data-frame]'),ctx=root.querySelector('canvas').getContext('2d');function draw(){const s=data[+f.value],cut=+r.value,ids=[...new Set(s.atoms.map(a=>a[0]))].sort((a,b)=>a-b),p=new Map(ids.map(x=>[x,x]));function find(x){while(p.get(x)!==x){p.set(x,p.get(p.get(x)));x=p.get(x)}return x}const tail=s.atoms.filter(a=>a[1]>=3);for(let i=0;i<tail.length;i++)for(let j=i+1;j<tail.length;j++){if(tail[i][0]===tail[j][0])continue;let dx=tail[i][2]-tail[j][2],dy=tail[i][3]-tail[j][3];dx-=s.lengths[0]*Math.round(dx/s.lengths[0]);dy-=s.lengths[1]*Math.round(dy/s.lengths[1]);if(dx*dx+dy*dy<=cut*cut){let a=find(tail[i][0]),b=find(tail[j][0]);if(a!==b)p.set(Math.max(a,b),Math.min(a,b))}}const groups=new Map();ids.forEach(m=>{let a=find(m);if(!groups.has(a))groups.set(a,[]);groups.get(a).push(m)});const ordered=[...groups.entries()].sort((a,b)=>b[1].length-a[1].length||a[0]-b[0]),colors=new Map(ordered.map((g,i)=>[g[0],`hsl(${(i*137.508)%360} 55% 40%)`])),sizes=ordered.map(g=>g[1].length);root.querySelector('[data-readout]').textContent=`t = ${s.time} τ · r* = ${cut.toFixed(2)} σ · ${zh?'团簇数':'Clusters'} ${groups.size} · ${zh?'最大团簇':'Largest'} ${Math.max(...sizes)} · ${zh?'单分子团簇':'Singletons'} ${sizes.filter(n=>n===1).length}`;ctx.fillStyle='#f8f7f2';ctx.fillRect(0,0,900,560);const x0=45,y0=35,w=475;ctx.strokeStyle='#6b8783';ctx.lineWidth=2;ctx.strokeRect(x0,y0,w,w);for(const a of s.atoms){const x=x0+w*a[2]/s.lengths[0],y=y0+w*(1-a[3]/s.lengths[1]);ctx.beginPath();ctx.arc(x,y,a[1]===2?4:3,0,2*Math.PI);ctx.fillStyle=colors.get(find(a[0]));ctx.fill();if(a[1]===2){ctx.strokeStyle='#173f46';ctx.lineWidth=1;ctx.stroke()}}ctx.fillStyle='#173f46';ctx.font='18px sans-serif';const lines=zh?['颜色：当前团簇分类','黑边圆：头珠；小圆：尾珠','周期边界参与距离计算。','同一颜色可以出现在盒两侧。','改变阈值只改变分类，','粒子的原始坐标保持不变。']:['Colour: current cluster membership','Outlined: heads; small dots: tails','Distances include periodic boundaries.','One colour may cross the box edges.','The threshold changes classification;','original coordinates remain fixed.'];lines.forEach((v,i)=>ctx.fillText(v,545,80+i*45));ctx.fillText(zh?'大小 × 团簇个数：':'Size × number of clusters:',545,380);const counts=new Map();sizes.forEach(n=>counts.set(n,(counts.get(n)||0)+1));let text=[...counts].map(([n,c])=>`${n} × ${c}`).join(', '),lines2=[];while(text.length>29){let n=text.lastIndexOf(',',29);if(n<0)n=29;lines2.push(text.slice(0,n));text=text.slice(n+1).trim()}lines2.push(text);lines2.slice(0,4).forEach((v,i)=>ctx.fillText(v,545,415+i*28));}r.addEventListener('input',draw);f.addEventListener('change',draw);root.querySelector('[data-reset]').addEventListener('click',()=>{r.value='1.2';f.value='3';draw()});draw()});